"""Differential fuzz: fast joint-residual engine vs FAdo reference vs oracle."""
import itertools, random, sys
sys.path[:0] = ['/workspace/project', '/opt/emicro-deps']
import syntax
from compiler import automata, compiler

DENY = automata.DENY


def evaluate(predicate, word, index):
    kind = predicate[0]
    if kind == 'match':
        return tuple(word) == tuple(index[n] for n in predicate[1])
    path = [index[n] for n in predicate[1]]
    if kind == 'startswith':
        return list(word)[:len(path)] == path
    if kind == 'endswith':
        return not path or list(word)[-len(path):] == path
    if kind == 'contains':
        if not path:
            return True
        return any(list(word)[i:i + len(path)] == path for i in range(len(word) - len(path) + 1))
    if kind == 'not':
        return not evaluate(predicate[1], word, index)
    if kind == 'and':
        return evaluate(predicate[1], word, index) and evaluate(predicate[2], word, index)
    return evaluate(predicate[1], word, index) or evaluate(predicate[2], word, index)


def allowed(rules, word, index):
    allow = drop = False
    for predicate, action in rules:
        if evaluate(predicate, word, index):
            if action:
                allow = True
            else:
                drop = True
    return allow and not drop


def run_image(image, word):
    state = 0
    for symbol in word:
        if state == DENY:
            return False
        state = image['rows'][state][symbol]
    if state == DENY:
        return False
    return image['accept'][state]


def random_predicate(rng, names, depth, allow_nonliteral, literal_pool, budget):
    if depth <= 0 or rng.random() < .45:
        kind = rng.choice(['match', 'match', 'match'] + (['startswith', 'endswith', 'contains'] if allow_nonliteral else []))
        limit = 4 if kind != 'match' else min(4, budget)
        length = rng.randint(0, max(0, min(limit, budget)))
        path = tuple(rng.choice(names) for _ in range(length))
        if kind != 'match':
            literal_pool.add((kind, path))
        return (kind, path)
    op = rng.choice(['and', 'or', 'not'])
    if op == 'not':
        return ('not', random_predicate(rng, names, depth - 1, allow_nonliteral, literal_pool, budget))
    return (op, random_predicate(rng, names, depth - 1, allow_nonliteral, literal_pool, budget // 2),
            random_predicate(rng, names, depth - 1, allow_nonliteral, literal_pool, budget - depth // 2))


def random_policy(rng, names):
    rules = []
    literal_pool = set()
    for _ in range(rng.randint(0, 5)):
        if rng.random() < .5:
            path = tuple(rng.choice(names) for _ in range(rng.randint(0, 4)))
            predicate = ('match', path)
        else:
            predicate = random_predicate(rng, names, rng.randint(1, 3), True, literal_pool, 8)
        rules.append((predicate, rng.random() < .6))
    text = []
    for predicate, allow in rules:
        text.append('%s %s;' % (render(predicate), 'allow' if allow else 'drop'))
    return ''.join(text), rules, literal_pool


def render(predicate):
    kind = predicate[0]
    if kind in ('match', 'startswith', 'endswith', 'contains'):
        return '%s(%s)' % (kind, ','.join(predicate[1]))
    if kind == 'not':
        return 'not(%s)' % render(predicate[1])
    return '(%s %s %s)' % (render(predicate[1]), kind, render(predicate[2]))


def main(rounds=4000, seed=1):
    rng = random.Random(seed)
    bad = 0
    for _ in range(rounds):
        size = rng.randint(1, 3)
        names = [chr(ord('A') + i) for i in range(size)]
        labels = rng.sample(range(1, 40), size)
        services = sorted([{'name': n, 'label': l} for n, l in zip(names, labels)], key=lambda s: s['label'])
        columns = [s['label'] for s in services]
        index = {s['name']: i for i, s in enumerate(services)}
        text, rules, literals = random_policy(rng, names)
        try:
            parsed, atoms, symbols = syntax.parse(text)
        except Exception as exc:
            print('PARSE', repr(text), exc); bad += 1; continue
        if len(literals) > 4:
            try:
                automata.compile_rules(parsed, columns, index)
                print('EXPECTED BOUNDS REJECT', text); bad += 1
            except syntax.PolicyError:
                pass
            continue
        fast = automata.compile_rules(parsed, columns, index)
        ref = compiler.compile_rules(parsed, columns, index)
        if fast != ref:
            print('ENGINE MISMATCH', text, fast, ref); bad += 1
        # oracle truth table over short words
        width = len(columns)
        for length in range(0, 7):
            for word in itertools.product(range(width), repeat=length):
                want = allowed(parsed, list(word), index)
                got = run_image(fast, word)
                if want != got:
                    print('ORACLE MISMATCH', text, word, want, got, fast); bad += 1
                    break
            else:
                continue
            break
        # canonical shape checks
        rows = fast['rows']
        if len(rows) != len(fast['accept']):
            print('SHAPE', text); bad += 1
        seen = {0}
        queue = [0]
        while queue:
            s = queue.pop(0)
            for t in rows[s]:
                if t != DENY and t not in seen:
                    seen.add(t); queue.append(t)
        if seen != set(range(len(rows))):
            print('NUMBERING', text, seen, len(rows)); bad += 1
        if len(rows) > 8192:
            print('ROWS', text); bad += 1
        cells = sum(1 for r in rows for t in r if t != DENY)
        if cells != fast['cells']:
            print('CELLS', text); bad += 1
        if any(any(t != DENY for t in rows[s]) and not any(fast['accept'][t] for t in _reach(rows, s)) for s in range(1, len(rows))):
            print('DEAD ROW', text, s); bad += 1
    print('rounds done, failures:', bad)


def _reach(rows, s):
    seen = {s}
    stack = [s]
    while stack:
        x = stack.pop()
        for t in rows[x]:
            if t != DENY and t not in seen:
                seen.add(t); stack.append(t)
    return seen


if __name__ == '__main__':
    main(int(sys.argv[1]) if len(sys.argv) > 1 else 4000, int(sys.argv[2]) if len(sys.argv) > 2 else 1)
